 Path(f'public-site/{p}.html').write_text(f'''<!doctype html><html lang="fa-AF" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="امینی گروپ؛ اجناس، نرخ‌ها، خدمات و ارتباط با شرکت."><title>{t} | امینی گروپ</title><script src="../assets/js/theme.js"></script><link rel="stylesheet" href="../assets/css/app.css"></head><body data-page="{p}"><header id="public-header" class="public-nav"></header><main class="public-main" id="public-app"><p>در حال دریافت معلومات…</p></main><footer id="public-footer" class="public-footer"></footer><script type="module" src="../assets/js/public.js"></script></body></html>''',encoding='utf8')
